import { test, expect } from '@playwright/test';

test.describe('Image Gallery Lightbox Modal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/gallery');
  });

  test('should open lightbox when clicking an image in the gallery', async ({ page }) => {
    // Verify lightbox is not visible initially
    const lightbox = page.getByRole('dialog');
    await expect(lightbox).not.toBeVisible();

    // Verify gallery is visible
    const gallery = page.getByRole('region', { name: /gallery/i });
    await expect(gallery).toBeVisible();

    // Get the first image in the gallery
    const firstImage = page.locator('[data-testid="gallery-image-1"]');
    await expect(firstImage).toBeVisible();

    // Click the first image to open lightbox
    await firstImage.click();

    // Verify lightbox is now visible
    await expect(lightbox).toBeVisible();

    // Verify lightbox has the correct title
    const lightboxTitle = page.getByText('Image Details');
    await expect(lightboxTitle).toBeVisible();

    // Verify lightbox contains image details
    const imageDetails = page.getByText('Sample Image');
    await expect(imageDetails).toBeVisible();

    // Verify close button is present
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify close button is clickable
    await expect(closeButton).toBeEnabled();

    // Close the lightbox
    await closeButton.click();

    // Verify lightbox is hidden
    await expect(lightbox).not.toBeVisible();

    // Verify gallery is still visible
    await expect(gallery).toBeVisible();
  });

  test('should handle multiple clicks on the same image in the gallery', async ({ page }) => {
    // Verify lightbox is not visible initially
    const lightbox = page.getByRole('dialog');
    await expect(lightbox).not.toBeVisible();

    // Verify gallery is visible
    const gallery = page.getByRole('region', { name: /gallery/i });
    await expect(gallery).toBeVisible();

    // Get the first image in the gallery
    const firstImage = page.locator('[data-testid="gallery-image-1"]');
    await expect(firstImage).toBeVisible();

    // Click the first image to open lightbox
    await firstImage.click();

    // Verify lightbox is now visible
    await expect(lightbox).toBeVisible();

    // Verify lightbox has the correct title
    const lightboxTitle = page.getByText('Image Details');
    await expect(lightboxTitle).toBeVisible();

    // Verify lightbox contains image details
    const imageDetails = page.getByText('Sample Image');
    await expect(imageDetails).toBeVisible();

    // Click the same image again to open lightbox
    await firstImage.click();

    // Verify lightbox is still visible
    await expect(lightbox).toBeVisible();

    // Verify lightbox title is still correct
    await expect(lightboxTitle).toBeVisible();

    // Verify lightbox contains the same image details
    await expect(imageDetails).toBeVisible();

    // Verify close button is still present
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Close the lightbox
    await closeButton.click();

    // Verify lightbox is hidden
    await expect(lightbox).not.toBeVisible();

    // Verify gallery is still visible
    await expect(gallery).toBeVisible();
  });
});
